# Let me approach this more systematically
# I'll look at all the character mappings needed:

inputs = ['gdec', 'auk', 'uxiwzi', 'ji', 'jchx']
outputs = ['ggec', 'auk', 'zviwzi', 'vfi', 'ahuax']

# Build all mappings
mappings = {}
for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            mappings[inp[i]] = outp[i]

# Check for conflicts
print("Character mappings:")
for char, replacement in mappings.items():
    print(f"'{char}' -> '{replacement}'")

# Also check if any character maps to different things
conflicts = {}
for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            if inp[i] in conflicts and conflicts[inp[i]] != outp[i]:
                print(f"Conflict: '{inp[i]}' maps to both '{conflicts[inp[i]]}' and '{outp[i]}'")
            conflicts[inp[i]] = outp[i]

print("\nConflicts found:", conflicts)

